ruleContent.content:
@js:
try {
  var h = String(result || '');
  var seg = h;
  var mc = h.match(/<div[^>]*id="chapcontent"[\s\S]*?<\/div>\s*<\/div>\s*<\/div>/);
  if (seg.indexOf('h-auto') < 0) seg = h;
  var re = /<img[^>]*>/g, m, c = [];
  while ((m = re.exec(seg)) !== null) {
    var tag = m[0];
    var cls = (tag.match(/class="([^"]*)"/) || [])[1] || '';
    var src = (tag.match(/src="([^"]*)"/) || [])[1] || '';
    if (!src) continue;
    if (cls.indexOf('h-auto') < 0) continue;
    if (cls.indexOf('lazyload') >= 0) continue;
    c.push(src);
  }
  var out = c.map(function(u){ return '<img src="' + u + '">'; }).join('\n');
  out;
} catch(e) { '' }

ruleToc.chapterList:
@js:
try {
    let html = String(result || '');
    // 正则提取章节（a标签 + 标题），不依赖元素API
    let re = /<a href="(\/chapter\/\d+)"[^>]*>[\s\S]*?<span class="chaptertitle[^"]*"[^>]*>([\s\S]*?)<\/span>/g;
    let arr = [], m, idx = 0;
    while ((m = re.exec(html)) !== null) {
        let title = m[2].replace(/<[^>]+>/g, '').trim();
        // 排序键：预告/序章特殊处理，其余按"第X话"
        let key = 999;
        if (/^预告/.test(title)) key = -1;
        else if (/^序章/.test(title)) key = 0.5;
        else { let tm = title.match(/第\s*(\d+)\s*话/); if (tm) key = parseInt(tm[1]); }
        arr.push({chapterName: title, chapterUrl: m[1], key: key, idx: idx++});
    }
    // 按话数排序，同话数保持原顺序
    arr.sort(function(a,b){ return a.key !== b.key ? a.key - b.key : a.idx - b.idx; });
    // 去重：识别出话数的(key<999)按话数去重，未识别的全部保留
    let seen = {}, out = [];
    arr.forEach(function(it){ if (it.key === 999 || !seen[it.key]) { seen[it.key] = 1; out.push({chapterName: it.chapterName, chapterUrl: it.chapterUrl}); } });
    out;
} catch(e) { [] }
